    head = [_cell(value) for value in header]
    body = []
    for row in rows:
        cells = [_cell(value) for value in row]
        if len(cells) > columns:
            raise ValueError(
                f"row has {len(cells)} cells but the header has {columns}"
            )
        body.append(cells + [""] * (columns - len(cells)))

    widths = [
        max([3, len(head[i])] + [len(cells[i]) for cells in body])
        for i in range(columns)
    ]
    lines = [[_pad(c, w, a) for c, w, a in zip(head, widths, align)]]
    lines.append([_delimiter(w, a) for w, a in zip(widths, align)])
    for cells in body:
        lines.append([_pad(c, w, a) for c, w, a in zip(cells, widths, align)])
    return "\n".join(_line(cells) for cells in lines)


def _split(line: str) -> list[str]:
    """Split a table line into stripped, unescaped cells."""
    line = line.strip()
    if line.startswith("|"):
        line = line[1:]
    if line.endswith("|") and not line.endswith("\\|"):
        line = line[:-1]
    return [cell.strip().replace("\\|", "|") for cell in _PIPE.split(line)]


def parse_table(
    text: str,
) -> tuple[list[str], list[list[str]], list[str | None]]:
    """Read a Markdown table into its header, rows, and alignments."""
    lines = text.strip().splitlines()
    if len(lines) < 2:
        raise ValueError("a table needs a header line and a delimiter line")
    header = _split(lines[0])
    columns = len(header)

    delimiter = _split(lines[1])
    if len(delimiter) != columns:
        raise ValueError(
            f"delimiter line has {len(delimiter)} cells "
            f"but the header has {columns}"
        )
    align: list[str | None] = []
    for cell in delimiter:
        if not _DELIMITER.fullmatch(cell):
            raise ValueError(f"invalid delimiter cell: {cell!r}")
        left, right = cell.startswith(":"), cell.endswith(":")
        if left and right:
            align.append("center")
        elif left:
            align.append("left")
        elif right:
            align.append("right")
        else:
            align.append(None)

    rows = []
    for number, line in enumerate(lines[2:], start=3):
        cells = _split(line)
        if len(cells) != columns:
            raise ValueError(
                f"line {number} has {len(cells)} cells "
                f"but the header has {columns}"
            )
        rows.append(cells)
    return header, rows, align
